## popup.js

```javascript
document.addEventListener("DOMContentLoaded", () => {
  const toggleSwitch  = document.getElementById("toggleSwitch");
  const statusText    = document.getElementById("statusText");
  const countNumber   = document.getElementById("countNumber");
  const rescanBtn     = document.getElementById("rescanBtn");

  // ── Helpers ──────────────────────────────────────────────────────────────

  function updateUI(enabled, count) {
    toggleSwitch.checked  = enabled;
    statusText.textContent = `Highlighting: ${enabled ? "ON" : "OFF"}`;
    countNumber.textContent = count ?? 0;
  }

  function sendToContent(message, callback) {
    chrome.tabs.query({ active: true, currentWindow: true }, tabs => {
      if (!tabs[0]?.id) return;
      chrome.tabs.sendMessage(tabs[0].id, message, response => {
        if (chrome.runtime.lastError) {
          console.warn("Content script not ready:", chrome.runtime.lastError.message);
          return;
        }
        if (callback) callback(response);
      });
    });
  }

  // ── Init: load saved state ────────────────────────────────────────────────

  chrome.storage.local.get(["highlightEnabled", "highlightCount"], result => {
    const enabled = result.highlightEnabled !== false;
    const count   = result.highlightCount   || 0;
    updateUI(enabled, count);
  });

  // Also ask the active tab directly for fresh data
  sendToContent({ action: "getStatus" }, response => {
    if (response) updateUI(response.enabled, response.count);
  });

  // ── Toggle ────────────────────────────────────────────────────────────────

  toggleSwitch.addEventListener("change", () => {
    const enabled = toggleSwitch.checked;
    chrome.storage.local.set({ highlightEnabled: enabled });
    sendToContent({ action: "toggle", enabled }, response => {
      if (response) updateUI(enabled, response.count);
    });
  });

  // ── Re-scan ───────────────────────────────────────────────────────────────

  rescanBtn.addEventListener("click", () => {
    rescanBtn.textContent = "⏳ Scanning…";
    rescanBtn.disabled    = true;

    sendToContent({ action: "rescan" }, response => {
      rescanBtn.textContent = "🔍 Re-scan Page";
      rescanBtn.disabled    = false;
      if (response) updateUI(true, response.count);
    });
  });
});
```

