    .footer-bottom-links a:hover { color: var(--white); }
    .footer-crown-notice {
      background: rgba(255,255,255,0.04);
      border-top: 1px solid rgba(255,255,255,0.06);
    }
    .footer-crown-notice-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 16px 24px;
      display: flex;
      align-items: center;
      gap: 12px;
      flex-wrap: wrap;
