    .footer-crown-notice svg { width: 20px; height: 20px; fill: rgba(255,255,255,0.3); flex-shrink: 0; }
    .footer-crown-notice p {
      font-size: 12px;
      color: rgba(255,255,255,0.3);
      line-height: 1.6;
    }
    .footer-crown-notice p a { color: rgba(255,255,255,0.45); text-decoration: underline; }

    /* ===== BACK TO TOP ===== */
    #back-top {
      position: fixed;
      bottom: 30px; right: 30px;
      width: 48px; height: 48px;
      background: var(--dark-blue);
      border: none;
      border-radius: 50%;
      color: white;
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: 0 4px 16px rgba(0,0,0,0.25);
      z-index: 300;
      opacity: 0;
      pointer-events: none;
      transform: translateY(10px);
      transition: all 0.3s;
    }
    #back-top.visible {
      opacity: 1;
      pointer-events: auto;
      transform: translateY(0);
    }
    #back-top:hover { background: var(--blue); transform: translateY(-3px); }
    #back-top svg { width: 20px; height: 20px; fill: white; }

    /* ===== RESPONSIVE ===== */
    @media (max-width: 1024px) {
      .hero-grid { grid-template-columns: 1fr; gap: 40px; }
      .hero-cards { max-width: 500px; }
      .footer-top-inner { grid-template-columns: 1fr 1fr; }
      .footer-brand { grid-column: span 2; }
      .app-inner { grid-template-columns: 1fr; }
      .app-visual { display: none; }
      .news-grid { grid-template-columns: 1fr; }
      .news-sidebar { display: grid; grid-template-columns: 1fr 1fr; }
      .access-inner { grid-template-columns: 1fr; }
    }
    @media (max-width: 768px) {
      nav.main-nav { display: none; }
