    // ===== ANIMATE STATS ON SCROLL =====
    function animateValue(el, start, end, duration, isFloat, prefix, suffix) {
      var range = end - start;
      var current = start;
      var increment = range / (duration / 16);
      var timer = setInterval(function() {
        current += increment;
        if ((increment > 0 && current >= end) || (increment < 0 && current <= end)) {
          current = end;
          clearInterval(timer);
        }
        el.innerHTML = prefix + (isFloat ? current.toFixed(1) : Math.floor(current)) + suffix;
      }, 16);
