function tokenize(text) {
    return text.toLowerCase()
        .replace(/[^а-яёa-z0-9\s]/gi, ' ')
        .split(/\s+/)
        .filter(w => w.length > 1);
}

function classify() {
    const text = document.getElementById('inputText').value.trim();
    if (!text) {
        alert('Пожалуйста, введите текст для классификации!');
        return;
    }

    const words = tokenize(text);
    if (words.length === 0) {
        alert('Не удалось обработать текст. Введите осмысленный текст.');
        return;
    }

    // Подсчёт совпадений для каждой темы
    const scores = topics.map(topic => {
        const matched = [];
        const matchedSet = new Set();

        words.forEach(word => {
