                const kwTokens = kw.toLowerCase().split(/\s+/);
                // Точное совпадение слова или вхождение ключевого слова
                if (word === kw || word.startsWith(kw) || kw.startsWith(word)) {
                    if (!matchedSet.has(kw)) {
                        matchedSet.add(kw);
                        matched.push(kw);
                    }
                }
            });
        });

        // Дополнительно ищем многословные фразы
        const fullText = text.toLowerCase();
        topic.keywords.forEach(kw => {
            if (kw.includes(' ') && fullText.includes(kw)) {
                if (!matchedSet.has(kw)) {
                    matchedSet.add(kw);
                    matched.push(kw);
                }
            }
        });

        // Взвешенный балл: учитываем уникальность совпадений
        const score = matched.length / Math.max(topic.keywords.length, 1) * 100;

        return {
            topic,
            score: Math.round(score * 100) / 100,
            rawCount: matched.length,
            matched
        };
    });

    // Сортировка
    scores.sort((a, b) => b.score - a.score || b.rawCount - a.rawCount);

    const best = scores[0];
    const totalScore = scores.reduce((s, r) => s + r.score, 0);

    // --- Показываем результат ---
    document.getElementById('noResult').style.display = 'none';
    const resultBox = document.getElementById('resultBox');
    resultBox.style.display = 'block';

