### 6.2 Autentifikation med JWT

```javascript
// authMiddleware.js
const jwt = require('jsonwebtoken');

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ message: 'Adgang nægtet: Intet token' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ message: 'Ugyldigt token' });
    }
    req.user = user;
    next();
  });
};

// authService.js
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const UserRepository = require('../repositories/userRepository');

class AuthService {
  async login(email, password) {
    const user = await UserRepository.findByEmail(email);

    if (!user) {
      throw new Error('Ugyldig email eller adgangskode');
    }

    const isValidPassword = await bcrypt.compare(password, user.password_hash);

    if (!isValidPassword) {
      throw new Error('Ugyldig email eller adgangskode');
    }

    const accessToken = jwt.sign(
      { userId: user.id, email: user.email, role: user.role },
      process.env.JWT_SECRET,
      { expiresIn: '1h' }
    );

    const refreshToken = jwt.sign(
      { userId: user.id },
      process.env.JWT_REFRESH_SECRET,
      { expiresIn: '7d' }
    );

    return { accessToken, refreshToken, user: { 
      id: user.id, 
      username: user.username, 
      email: user.email 
    }};
  }

  async register(userData) {
    const saltRounds = 10;
    const passwordHash = await bcrypt.hash(userData.password, saltRounds);

    const newUser = await UserRepository.create({
      ...userData,
      passwordHash,
    });

    return newUser;
  }
}

module.exports = new AuthService();
module.exports.authenticateToken = authenticateToken;
```

### 6.3 Socket.io Handler

```javascript
// socketHandler.js
const jwt = require('jsonwebtoken');

const socketHandler = (io) => {
  // Middleware til autentifikation af WebSocket-forbindelser
  io.use((socket, next) => {
    const token = socket.handshake.auth.token;

    if (!token) {
      return next(new Error('Autentifikation påkrævet'));
    }

    jwt.verify(token, process.env.JWT_SECRET, (err, decoded) => {
      if (err) {
        return next(new Error('Ugyldigt token'));
      }
      socket.userId = decoded.userId;
      socket.userEmail = decoded.email;
      next();
    });
  });

  // Spor forbundne brugere
  const connectedUsers = new Map();

  io.on('connection', (socket) => {
    console.log(`Bruger ${socket.userId} forbundet`);

    // Tilføj bruger til aktive brugere
    connectedUsers.set(socket.userId, socket.id);

    // Informer alle om ny forbundet bruger
    io.emit('userConnected', {
      userId: socket.userId,
      connectedUsers: connectedUsers.size,
    });

    // Håndter beskeder
    socket.on('sendMessage', (data) => {
      const message = {
        from: socket.userId,
        content: data.content,
        timestamp: new Date().toISOString(),
      };

      // Broadcast til alle eller specifik modtager
      if (data.recipientId) {
        const recipientSocketId = connectedUsers.get(data.recipientId);
        if (recipientSocketId) {
          io.to(recipientSocketId).emit('newMessage', message);
        }
      } else {
        io.emit('newMessage', message);
      }
    });

    // Håndter rum (rooms)
    socket.on('joinRoom', (roomId) => {
      socket.join(roomId);
      socket.to(roomId).emit('userJoinedRoom', { 
        userId: socket.userId, 
        roomId 
      });
    });

    socket.on('leaveRoom', (roomId) => {
      socket.leave(roomId);
      socket.to(roomId).emit('userLeftRoom', { 
        userId: socket.userId, 
        roomId 
      });
    });

    // Håndter afbrydelse
    socket.on('disconnect', () => {
      connectedUsers.delete(socket.userId);
      io.emit('userDisconnected', {
        userId: socket.userId,
        connectedUsers: connectedUsers.size,
      });
      console.log(`Bruger ${socket.userId} afbrudt`);
    });
  });
};

module.exports = socketHandler;
```

