### 7.3 Redis Cache

Redis anvendes til at reducere databasebelastning og forbedre responstider:

```javascript
// cacheService.js
const redis = require('redis');

class CacheService {
  constructor() {
    this.client = redis.createClient({
      url: process.env.REDIS_URL || 'redis://localhost:6379',
    });

    this.client.on('error', (err) => {
      console.error('Redis fejl:', err);
    });

    this.client.connect();
  }

  async get(key) {
    try {
      const data = await this.client.get(key);
      return data ? JSON.parse(data) : null;
    } catch (error) {
      console.error('Cache get fejl:', error);
      return null;
    }
  }

  async set(key, value, ttlSeconds = 3600) {
    try {
      await this.client.setEx(
        key, 
        ttlSeconds, 
        JSON.stringify(value)
      );
    } catch (error) {
      console.error('Cache set fejl:', error);
    }
  }

  async delete(key) {
    try {
      await this.client.del(key);
    } catch (error) {
      console.error('Cache delete fejl:', error);
    }
  }

  // Cache-through pattern
  async getOrSet(key, fetchFunction, ttlSeconds = 3600) {
    const cached = await this.get(key);

    if (cached) {
      console.log(`Cache hit: ${key}`);
      return cached;
    }

    console.log(`Cache miss: ${key}`);
    const data = await fetchFunction();
    await this.set(key, data, ttlSeconds);
    return data;
  }
}

module.exports = new CacheService();
```

