def process_uploaded_files(uploaded_files):
    """Procesa los archivos PDF subidos."""
    processor = PDFProcessor()
    new_files = [f for f in uploaded_files 
                 if f.name not in st.session_state.processed_files]

    if not new_files:
        st.info("ℹ️ Todos los archivos ya están procesados")
        return

    st.markdown("### ⏳ Procesando documentos...")
    progress_bar = st.progress(0)
    status_text = st.empty()

    for idx, uploaded_file in enumerate(new_files):
        status_text.text(f"📄 Procesando: {uploaded_file.name}")
        progress = (idx + 1) / len(new_files)

        try:
            # Procesar PDF
            with st.spinner(f"Analizando {uploaded_file.name}..."):
                doc_data = processor.process_pdf(uploaded_file)

            if doc_data:
                st.session_state.documents[uploaded_file.name] = doc_data
                st.session_state.processed_files.append(uploaded_file.name)
                st.session_state.analytics['docs_processed'] += 1

                # Actualizar motor QA
                update_qa_engine()

                progress_bar.progress(progress)
                st.success(f"✅ {uploaded_file.name} procesado exitosamente "
                          f"({doc_data['num_pages']} páginas, "
                          f"{doc_data['word_count']} palabras)")
            else:
                st.error(f"❌ Error procesando {uploaded_file.name}")

        except Exception as e:
            st.error(f"❌ Error en {uploaded_file.name}: {str(e)}")

    progress_bar.progress(1.0)
    status_text.text("✅ ¡Procesamiento completado!")
    time.sleep(1)
    status_text.empty()

def process_pdf_from_url(url: str):
    """Descarga y procesa un PDF desde una URL."""
    try:
        import requests
        from io import BytesIO

        with st.spinner("⬇️ Descargando PDF..."):
            response = requests.get(url, timeout=30)
            response.raise_for_status()

            # Crear objeto similar a uploaded_file
            pdf_bytes = BytesIO(response.content)
            filename = url.split('/')[-1] or "documento_web.pdf"

            processor = PDFProcessor()
            doc_data = processor.process_pdf_bytes(pdf_bytes, filename)

            if doc_data:
                st.session_state.documents[filename] = doc_data
                st.session_state.processed_files.append(filename)
                update_qa_engine()
                st.success(f"✅ PDF descargado y procesado: {filename}")
            else:
                st.error("❌ No se pudo procesar el PDF de la URL")

    except Exception as e:
        st.error(f"❌ Error descargando PDF: {str(e)}")

