                ["Detallado", "Conciso", "Técnico", "Simple"]
            )

    # Botones de acción
    col1, col2, col3, col4 = st.columns([2, 1, 1, 1])

    with col1:
        ask_button = st.button(
            "🚀 Hacer Pregunta",
            type="primary",
            use_container_width=True,
            disabled=not question.strip()
        )

    with col2:
        if st.button("🎲 Pregunta Aleatoria", use_container_width=True):
            import random
            all_suggestions = get_all_suggestions()
            if all_suggestions:
                st.session_state.current_question = random.choice(all_suggestions)
                st.rerun()

    with col3:
        if st.button("🗑️ Limpiar", use_container_width=True):
            st.session_state.current_question = ""
            st.rerun()

    with col4:
        if st.button("📋 Copiar última", use_container_width=True):
            if st.session_state.chat_history:
                last_answer = st.session_state.chat_history[-1]['answer']
                st.code(last_answer, language=None)

    # Procesar pregunta
    if ask_button and question.strip():
        process_question(question, show_sources, show_confidence, language, response_style)

def process_question(question: str, show_sources: bool, show_confidence: bool,
                     language: str, response_style: str):
    """Procesa y responde una pregunta."""
    start_time = time.time()

    with st.spinner("🤔 Analizando tu pregunta..."):
        try:
            # Obtener el motor QA
            qa_engine = st.session_state.qa_engine

            if not qa_engine:
                st.error("❌ El motor QA no está inicializado. Recarga los documentos.")
                return

            # Procesar según el tipo de pregunta
            question_type = st.session_state.question_type

            # Crear prompt enriquecido
            enhanced_prompt = create_enhanced_prompt(
                question, question_type, language, response_style
            )

            # Obtener respuesta
            result = qa_engine.answer_question(
                enhanced_prompt,
                selected_docs=st.session_state.selected_docs,
                question_type=question_type
            )

            response_time = time.time() - start_time

            # Actualizar estadísticas
            st.session_state.analytics['questions_asked'] += 1
            st.session_state.analytics['total_response_times'].append(response_time)

            # Crear entrada en el historial
            chat_entry = {
                'id': len(st.session_state.chat_history) + 1,
                'question': question,
                'answer': result.get('answer', 'No se pudo generar respuesta'),
                'sources': result.get('sources', []),
                'confidence': result.get('confidence', 0),
                'question_type': question_type,
                'response_time': response_time,
                'timestamp': datetime.now().strftime("%H:%M:%S"),
                'show_sources': show_sources,
                'show_confidence': show_confidence,
                'options': result.get('options', [])
            }

            st.session_state.chat_history.append(chat_entry)
            st.session_state.current_question = ""

            # Mostrar respuesta inmediatamente
            render_answer(chat_entry)

        except Exception as e:
            st.error(f"❌ Error procesando la pregunta: {str(e)}")
            st.exception(e)

def render_answer(chat_entry: dict):
    """Renderiza una respuesta individual."""
    with st.container():
        st.markdown(f"""
        <div class="answer-box">
            <div class="answer-header">
                🤖 Respuesta #{chat_entry['id']} 
                <small style='color: #718096;'>— {chat_entry['timestamp']}</small>
            </div>
        </div>
        """, unsafe_allow_html=True)

        # Pregunta
        st.markdown(f"**❓ Pregunta:** {chat_entry['question']}")

        st.divider()

        # Respuesta principal
        if chat_entry['question_type'] == 'multiple_choice' and chat_entry['options']:
            render_multiple_choice(chat_entry)
        else:
            st.markdown(f"**💬 Respuesta:**\n\n{chat_entry['answer']}")

        # Métricas de la respuesta
        col1, col2, col3 = st.columns(3)

        with col1:
            if chat_entry.get('show_confidence'):
                confidence = chat_entry.get('confidence', 0)
                st.metric(
                    "📊 Confianza",
                    f"{confidence:.1%}",
                    help="Nivel de confianza en la respuesta"
                )

        with col2:
            st.metric(
                "⏱️ Tiempo",
                f"{chat_entry['response_time']:.2f}s"
            )

        with col3:
            source_count = len(chat_entry.get('sources', []))
            st.metric(
                "📎 Fuentes",
                source_count
            )

        # Fuentes
        if chat_entry.get('show_sources') and chat_entry.get('sources'):
            with st.expander("📎 Ver Fuentes"):
                for source in chat_entry['sources']:
                    st.markdown(f"""
                    <span class="source-badge">
                        📄 {source.get('document', 'Desconocido')} 
                        - Pág. {source.get('page', 'N/A')}
                    </span>
                    """, unsafe_allow_html=True)

                    if source.get('text'):
                        with st.expander(f"Ver extracto de {source.get('document', 'Doc')}"):
                            st.markdown(f"> {source['text'][:500]}...")

        # Acciones de la respuesta
        col1, col2, col3, col4 = st.columns(4)

        with col1:
            if st.button("👍 Útil", key=f"like_{chat_entry['id']}"):
                st.success("¡Gracias por tu feedback!")

        with col2:
            if st.button("👎 Mejorar", key=f"dislike_{chat_entry['id']}"):
                st.info("Feedback registrado para mejoras")

        with col3:
            if st.button("🔖 Guardar", key=f"save_{chat_entry['id']}"):
                save_to_bookmarks(chat_entry)

        with col4:
            if st.button("🔄 Regenerar", key=f"regen_{chat_entry['id']}"):
                process_question(
                    chat_entry['question'],
                    chat_entry['show_sources'],
                    chat_entry['show_confidence'],
                    "Español",
                    "Detallado"
                )

