def perform_search(query: str, search_type: str, filter_docs: list,
                   min_relevance: float, max_results: int):
    """Realiza la búsqueda en los documentos."""
    with st.spinner("🔍 Buscando..."):
        try:
            search_engine = st.session_state.search_engine

            if not search_engine:
                st.error("❌ Motor de búsqueda no inicializado")
                return

            results = search_engine.search(
                query=query,
                search_type=search_type,
                filter_docs=filter_docs,
                max_results=max_results
            )

            # Filtrar por relevancia
            filtered_results = [r for r in results if r.get('score', 0) >= min_relevance]

            # Guardar en historial
            st.session_state.search_history.append({
                'query': query,
                'results': len(filtered_results),
                'timestamp': datetime.now().strftime("%H:%M:%S")
            })

            # Mostrar resultados
            if filtered_results:
                st.success(f"✅ Se encontraron {len(filtered_results)} resultados")

                for idx, result in enumerate(filtered_results):
                    with st.expander(
                        f"📄 {result['document']} | Pág. {result.get('page', 'N/A')} | "
                        f"Relevancia: {result.get('score', 0):.1%}",
                        expanded=idx < 3
                    ):
                        # Resaltar términos de búsqueda
                        text = result.get('text', '')
                        highlighted_text = highlight_search_terms(text, query)
                        st.markdown(highlighted_text, unsafe_allow_html=True)

                        col1, col2 = st.columns(2)
                        with col1:
                            if st.button(
                                "❓ Hacer pregunta sobre esto",
                                key=f"ask_{idx}"
                            ):
                                st.session_state.current_question = (
                                    f"Explica detalladamente: {result['text'][:100]}..."
                                )
                                st.rerun()
                        with col2:
                            if st.button(
                                "🔖 Guardar resultado",
                                key=f"save_search_{idx}"
                            ):
                                st.session_state.bookmarks.append({
                                    'type': 'search_result',
                                    'content': result,
                                    'query': query
                                })
                                st.success("✅ Guardado en marcadores")
            else:
                st.warning("🔍 No se encontraron resultados. Intenta con otros términos.")

        except Exception as e:
            st.error(f"❌ Error en la búsqueda: {str(e)}")

