def update_qa_engine():
    """Actualiza el motor QA con los documentos actuales."""
    try:
        if st.session_state.documents:
            qa_engine = QAEngine(
                api_provider=st.session_state.get('api_provider', 'HuggingFace'),
                temperature=st.session_state.get('temperature', 0.0),
                max_tokens=st.session_state.get('max_tokens', 500),
                chunk_size=st.session_state.get('chunk_size', 1000),
                top_k=st.session_state.get('top_k', 4)
            )

            qa_engine.load_documents(st.session_state.documents)
            st.session_state.qa_engine = qa_engine

            # Actualizar motor de búsqueda
            search_engine = SearchEngine()
            search_engine.index_documents(st.session_state.documents)
            st.session_state.search_engine = search_engine

    except Exception as e:
        st.error(f"❌ Error inicializando motor QA: {str(e)}")

def clear_all_documents():
    """Limpia todos los documentos cargados."""
    st.session_state.documents = {}
    st.session_state.processed_files = []
    st.session_state.qa_engine = None
    st.session_state.search_engine = None
    st.session_state.chat_history = []
    st.rerun()

def reinitialize_engines():
    """Reinicializa los motores QA y de búsqueda."""
    with st.spinner("🔄 Reinicializando..."):
        update_qa_engine()
    st.success("✅ Motores reinicializados")

def remove_document(filename: str):
    """Elimina un documento específico."""
    if filename in st.session_state.documents:
        del st.session_state.documents[filename]
    if filename in st.session_state.processed_files:
        st.session_state.processed_files.remove(filename)
    update_qa_engine()

