def get_question_suggestions():
    """Obtiene sugerencias de preguntas según el tipo seleccionado."""
    suggestions_map = {
        'open': [
            "¿Cuál es el tema principal de este documento?",
            "¿Cuáles son las conclusiones más importantes?",
            "¿Qué problemas se identifican en el texto?",
            "¿Cuáles son las recomendaciones del autor?"
        ],
        'multiple_choice': [
            "¿Cuál es el objetivo principal del documento?",
            "¿Cuándo fue escrito este documento?",
            "¿Quién es el autor principal?",
            "¿Cuál es la metodología utilizada?"
        ],
        'summary': [
            "Resume el documento completo",
            "Resume los puntos más importantes",
            "Proporciona un resumen ejecutivo",
            "Resumen por secciones"
        ],
        'comparison': [
            "Compara los diferentes documentos cargados",
            "¿En qué difieren los documentos?",
            "¿Qué tienen en común los documentos?",
            "Compara las metodologías de los documentos"
        ],
        'definition': [
            "¿Qué es [término específico] según el documento?",
            "Define los conceptos clave del texto",
            "¿Cómo se define [concepto] en este contexto?",
            "Explica el significado de los términos técnicos"
        ],
        'timeline': [
            "¿Cuál es la cronología de eventos mencionados?",
            "Ordena los eventos por fecha",
            "¿Cuándo ocurrieron los eventos principales?",
            "Crea una línea de tiempo del contenido"
        ]
    }

    return suggestions_map.get(
        st.session_state.question_type,
        suggestions_map['open']
    )

def get_all_suggestions():
    """Obtiene todas las sugerencias disponibles."""
    all_suggestions = []
    for qtype in ['open', 'summary', 'comparison', 'definition']:
        suggestions = get_question_suggestions()
        all_suggestions.extend(suggestions)
    return all_suggestions

def create_enhanced_prompt(question: str, question_type: str,
                            language: str, response_style: str) -> str:
    """Crea un prompt enriquecido según el tipo de pregunta."""
    style_instructions = {
        "Detallado": "Proporciona una respuesta detallada y completa con ejemplos cuando sea posible.",
        "Conciso": "Proporciona una respuesta concisa y directa en no más de 3 oraciones.",
        "Técnico": "Usa terminología técnica apropiada y proporciona detalles específicos.",
        "Simple": "Explica de manera simple y fácil de entender, evitando tecnicismos."
    }

    type_instructions = {
        'open': "",
        'multiple_choice': "\nGenera 4 opciones de respuesta (A, B, C, D) donde la primera sea la correcta.",
        'summary': "\nProporciona un resumen estructurado con puntos clave.",
        'comparison': "\nCompara y contrasta los aspectos relevantes encontrados en los documentos.",
        'definition': "\nDefine claramente el término o concepto preguntado.",
        'timeline': "\nOrdena los eventos cronológicamente si es aplicable."
    }

    language_map = {
        "Español": "Responde en español.",
        "English": "Answer in English.",
        "Français": "Répondez en français.",
        "Deutsch": "Antworten Sie auf Deutsch.",
        "Português": "Responda em português."
    }

    enhanced = question
    enhanced += f"\n\n{style_instructions.get(response_style, '')}"
    enhanced += type_instructions.get(question_type, '')
    enhanced += f"\n{language_map.get(language, 'Responde en español.')}"

    return enhanced

def highlight_search_terms(text: str, query: str) -> str:
    """Resalta los términos de búsqueda en el texto."""
    import re
    terms = query.split()
    highlighted = text

    for term in terms:
        pattern = re.compile(re.escape(term), re.IGNORECASE)
        highlighted = pattern.sub(
            f'<mark style="background-color: #ffd700;">{term}</mark>',
            highlighted
        )

    return highlighted

def extract_topics(doc_data: dict) -> list:
    """Extrae temas principales de un documento."""
    try:
        from collections import Counter
        import re

        text = doc_data.get('text', '')
        words = re.findall(r'\b[A-Za-záéíóúÁÉÍÓÚñÑ]{4,}\b', text.lower())

        # Palabras de parada en español
        stop_words = {
            'para', 'como', 'pero', 'más', 'este', 'esta', 'estos', 'estas',
            'que', 'del', 'los', 'las', 'por', 'con', 'una', 'uno', 'también',
            'muy', 'todo', 'todos', 'todas', 'sobre', 'entre', 'cuando', 'donde',
            'desde', 'hasta', 'cada', 'puede', 'debe', 'tiene', 'hacer', 'sido'
        }

        filtered_words = [w for w in words if w not in stop_words]
        word_freq = Counter(filtered_words).most_common(10)

        return word_freq

    except Exception:
        return []

def summarize_page(text: str) -> str:
    """Genera un resumen de una página."""
    # Implementación básica sin API
    sentences = text.split('.')[:3]
    return '. '.join(sentences) + '...' if sentences else "No se pudo generar resumen"

