"""
Módulo para procesamiento de archivos PDF.
"""

import pdfplumber
import PyPDF2
from io import BytesIO
from datetime import datetime
from typing import Optional, Dict, Any
import re
import streamlit as st


class PDFProcessor:
    """Clase para procesar y extraer texto de archivos PDF."""

    def __init__(self):
        self.supported_formats = ['.pdf']

    def process_pdf(self, uploaded_file) -> Optional[Dict[str, Any]]:
        """
        Procesa un archivo PDF subido a través de Streamlit.

        Args:
            uploaded_file: Archivo subido vía st.file_uploader

        Returns:
            Diccionario con el contenido y metadata del PDF
        """
        try:
            pdf_bytes = BytesIO(uploaded_file.read())
            return self._extract_content(pdf_bytes, uploaded_file.name, 
                                         uploaded_file.size)
        except Exception as e:
            st.error(f"Error procesando PDF: {str(e)}")
            return None

    def process_pdf_bytes(self, pdf_bytes: BytesIO, 
                          filename: str) -> Optional[Dict[str, Any]]:
        """
        Procesa un PDF desde bytes.

        Args:
            pdf_bytes: Contenido del PDF en bytes
            filename: Nombre del archivo

        Returns:
            Diccionario con el contenido y metadata
        """
        return self._extract_content(pdf_bytes, filename, len(pdf_bytes.getvalue()))

    def _extract_content(self, pdf_bytes: BytesIO, filename: str, 
                         file_size: int) -> Optional[Dict[str, Any]]:
        """
        Extrae el contenido completo de un PDF.
        """
        try:
            pages_text = []
            metadata = {}

            # Intentar con pdfplumber (mejor calidad)
            try:
                with pdfplumber.open(pdf_bytes) as pdf:
                    metadata = self._extract_metadata_pdfplumber(pdf)

                    for page_num, page in enumerate(pdf.pages):
                        text = page.extract_text() or ""
                        text = self._clean_text(text)
                        pages_text.append(text)

            except Exception:
                # Fallback a PyPDF2
                pdf_bytes.seek(0)
                reader = PyPDF2.PdfReader(pdf_bytes)
                metadata = self._extract_metadata_pypdf2(reader)

                for page in reader.pages:
                    text = page.extract_text() or ""
                    text = self._clean_text(text)
                    pages_text.append(text)

            # Combinar todo el texto
            full_text = "\n\n".join(pages_text)

            # Calcular estadísticas
            word_count = len(full_text.split())
            char_count = len(full_text)

            return {
                'filename': filename,
                'text': full_text,
                'pages': pages_text,
                'num_pages': len(pages_text),
                'word_count': word_count,
                'char_count': char_count,
                'file_size': file_size / 1024,  # KB
                'metadata': metadata,
                'processed_at': datetime.now().strftime("%Y-%m-%d %H:%M"),
                'language': self._detect_language(full_text[:1000])
            }

        except Exception as e:
            st.error(f"Error extrayendo contenido: {str(e)}")
            return None

    def _extract_metadata_pdfplumber(self, pdf) -> dict:
        """Extrae metadata con pdfplumber."""
        try:
            meta = pdf.metadata or {}
            return {
                'title': meta.get('Title', ''),
                'author': meta.get('Author', ''),
                'subject': meta.get('Subject', ''),
                'creator': meta.get('Creator', ''),
                'creation_date': meta.get('CreationDate', ''),
                'modification_date': meta.get('ModDate', '')
            }
        except Exception:
            return {}

    def _extract_metadata_pypdf2(self, reader: PyPDF2.PdfReader) -> dict:
        """Extrae metadata con PyPDF2."""
        try:
            meta = reader.metadata or {}
            return {
                'title': meta.get('/Title', ''),
                'author': meta.get('/Author', ''),
                'subject': meta.get('/Subject', ''),
                'creator': meta.get('/Creator', ''),
                'creation_date': str(meta.get('/CreationDate', '')),
                'modification_date': str(meta.get('/ModDate', ''))
            }
        except Exception:
            return {}

    def _clean_text(self, text: str) -> str:
        """Limpia y normaliza el texto extraído."""
        # Eliminar caracteres de control
        text = re.sub(r'[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]', '', text)

        # Normalizar espacios en blanco
        text = re.sub(r' +', ' ', text)
        text = re.sub(r'\n{3,}', '\n\n', text)

        # Eliminar líneas vacías excesivas
        lines = [line.strip() for line in text.split('\n')]
        lines = [line for line in lines if line]

        return '\n'.join(lines)

    def _detect_language(self, text: str) -> str:
        """Detecta el idioma del texto."""
        spanish_words = ['el', 'la', 'de', 'que', 'en', 'y', 'los', 'del', 'se', 'las']
        english_words = ['the', 'of', 'and', 'to', 'in', 'is', 'it', 'that', 'was', 'for']

        words = text.lower().split()

        spanish_count = sum(1 for w in words if w in spanish_words)
        english_count = sum(1 for w in words if w in english_words)

        if spanish_count > english_count:
            return 'es'
        elif english_count > spanish_count:
            return 'en'
        else:
            return 'unknown'
