"""
Motor de Preguntas y Respuestas usando LangChain.
"""

from typing import Dict, List, Any, Optional
import os
import streamlit as st


class QAEngine:
    """
    Motor de Q&A que usa LangChain para responder preguntas
    sobre el contenido de los documentos PDF.
    """

    def __init__(self, api_provider: str = "HuggingFace",
                 temperature: float = 0.0,
                 max_tokens: int = 500,
                 chunk_size: int = 1000,
                 top_k: int = 4):

        self.api_provider = api_provider
        self.temperature = temperature
        self.max_tokens = max_tokens
        self.chunk_size = chunk_size
        self.top_k = top_k
        self.vectorstore = None
        self.qa_chain = None
        self.documents_loaded = False

    def load_documents(self, documents: Dict[str, Any]):
        """
        Carga y procesa los documentos en el vectorstore.

        Args:
            documents: Diccionario de documentos procesados
        """
        from langchain.text_splitter import RecursiveCharacterTextSplitter
        from langchain.schema import Document

        try:
            # Preparar textos
            docs = []
            text_splitter = RecursiveCharacterTextSplitter(
                chunk_size=self.chunk_size,
                chunk_overlap=200,
                length_function=len,
                separators=["\n\n", "\n", " ", ""]
            )

            for filename, doc_data in documents.items():
                # Dividir por páginas para mejor rastreo de fuentes
                for page_num, page_text in enumerate(doc_data.get('pages', [])):
                    if page_text.strip():
                        chunks = text_splitter.split_text(page_text)

                        for chunk in chunks:
                            docs.append(Document(
                                page_content=chunk,
                                metadata={
                                    'source': filename,
                                    'page': page_num + 1,
                                    'document': filename
                                }
                            ))

            if not docs:
                raise ValueError("No se encontró texto en los documentos")

            # Crear vectorstore
            self.vectorstore = self._create_vectorstore(docs)

            # Crear cadena QA
            self.qa_chain = self._create_qa_chain()
            self.documents_loaded = True

        except Exception as e:
            st.error(f"Error cargando documentos en QA Engine: {str(e)}")
            raise

    def _create_vectorstore(self, docs):
        """Crea el vectorstore para búsqueda semántica."""
        try:
            # Intentar con OpenAI embeddings si está disponible
            if self.api_provider == "OpenAI" and os.getenv("OPENAI_API_KEY"):
                from langchain.embeddings import OpenAIEmbeddings
                from langchain.vectorstores import FAISS

                embeddings = OpenAIEmbeddings()
                return FAISS.from_documents(docs, embeddings)

            else:
                # Usar HuggingFace embeddings (gratuito)
                from langchain.embeddings import HuggingFaceEmbeddings
                from langchain.vectorstores import FAISS

                embeddings = HuggingFaceEmbeddings(
                    model_name="sentence-transformers/paraphrase-multilingual-MiniLM-L12-v2",
                    model_kwargs={'device': 'cpu'},
                    encode_kwargs={'normalize_embeddings': True}
                )
                return FAISS.from_documents(docs, embeddings)

        except Exception as e:
            # Fallback: vectorstore simple basado en TF-IDF
            st.warning(f"⚠️ Usando búsqueda simplificada: {str(e)}")
            return self._create_simple_vectorstore(docs)

    def _create_simple_vectorstore(self, docs):
        """Crea un vectorstore simple como fallback."""
        from sklearn.feature_extraction.text import TfidfVectorizer
        import numpy as np

        class SimpleVectorStore:
            def __init__(self, documents):
                self.documents = documents
                self.texts = [d.page_content for d in documents]
                self.vectorizer = TfidfVectorizer(
                    max_features=5000,
                    stop_words=None
                )
                self.matrix = self.vectorizer.fit_transform(self.texts)

            def similarity_search_with_score(self, query: str, k: int = 4):
                from sklearn.metrics.pairwise import cosine_similarity

                query_vec = self.vectorizer.transform([query])
                scores = cosine_similarity(query_vec, self.matrix)[0]
                top_indices = np.argsort(scores)[::-1][:k]

                results = []
                for idx in top_indices:
                    if scores[idx] > 0:
                        results.append((self.documents[idx], float(scores[idx])))

                return results

        return SimpleVectorStore(docs)

    def _create_qa_chain(self):
        """Crea la cadena de preguntas y respuestas."""
        try:
            if self.api_provider == "OpenAI" and os.getenv("OPENAI_API_KEY"):
                from langchain.llms import OpenAI
                from langchain.chains import RetrievalQA
                from langchain.prompts import PromptTemplate

                llm = OpenAI(
                    temperature=self.temperature,
                    max_tokens=self.max_tokens,
                    openai_api_key=os.getenv("OPENAI_API_KEY")
                )

                prompt_template = """Usa el siguiente contexto para responder la pregunta.
                Si no encuentras la respuesta en el contexto, dilo claramente.

                Contexto:
                {context}

                Pregunta: {question}

                Respuesta detallada:"""

                prompt = PromptTemplate(
                    template=prompt_template,
                    input_variables=["context", "question"]
                )

                return RetrievalQA.from_chain_type(
                    llm=llm,
                    chain_type="stuff",
                    retriever=self.vectorstore.as_retriever(
                        search_kwargs={"k": self.top_k}
                    ),
                    chain_type_kwargs={"prompt": prompt},
                    return_source_documents=True
                )

            else:
                # Motor QA personalizado sin dependencia de LLM
                return self._create_custom_qa_chain()

        except Exception as e:
            st.warning(f"⚠️ Usando motor QA simplificado: {str(e)}")
            return self._create_custom_qa_chain()

    def _create_custom_qa_chain(self):
        """Crea un motor QA personalizado sin API externa."""
        class CustomQAChain:
            def __init__(self, vectorstore, top_k):
                self.vectorstore = vectorstore
                self.top_k = top_k

            def __call__(self, inputs: dict) -> dict:
                query = inputs.get('query', '')

                # Obtener documentos relevantes
                results = self.vectorstore.similarity_search_with_score(
                    query, k=self.top_k
                )

                # Construir respuesta con extractos relevantes
                context_parts = []
                source_docs = []

                for doc, score in results:
                    context_parts.append(doc.page_content)
                    source_docs.append(doc)

                # Generar respuesta básica
                if context_parts:
                    answer = self._generate_answer(query, context_parts)
                else:
                    answer = "No se encontró información relevante en los documentos."

                return {
                    'result': answer,
                    'source_documents': source_docs
                }

            def _generate_answer(self, query: str, contexts: List[str]) -> str:
                """Genera una respuesta básica extrayendo información relevante."""
                combined_context = " ".join(contexts[:3])

                # Estrategia simple: encontrar oraciones relevantes
                sentences = combined_context.replace('\n', ' ').split('.')

                query_words = set(query.lower().split())
                relevant_sentences = []

                for sentence in sentences:
                    sentence_words = set(sentence.lower().split())
                    overlap = len(query_words & sentence_words) / max(len(query_words), 1)

                    if overlap > 0.2 and len(sentence.strip()) > 30:
                        relevant_sentences.append(sentence.strip())

                if relevant_sentences:
                    answer = '. '.join(relevant_sentences[:5])
                    return answer + ".\n\n*(Respuesta generada a partir del contexto del documento)*"
                else:
                    return f"Información encontrada:\n\n{combined_context[:500]}..."

        return CustomQAChain(self.vectorstore, self.top_k)

    def answer_question(self, question: str, 
                        selected_docs: Optional[List[str]] = None,
                        question_type: str = "open") -> Dict[str, Any]:
        """
        Responde una pregunta basada en los documentos cargados.

        Args:
            question: La pregunta a responder
            selected_docs: Lista de documentos a considerar
            question_type: Tipo de pregunta

        Returns:
            Diccionario con respuesta, fuentes y confianza
        """
        if not self.documents_loaded:
            raise ValueError("No hay documentos cargados")

        try:
            result = self.qa_chain({'query': question})

            # Extraer respuesta
            answer = result.get('result', 'No se pudo generar respuesta')
            source_docs = result.get('source_documents', [])

            # Procesar fuentes
            sources = []
            seen_sources = set()

            for doc in source_docs:
                source_key = f"{doc.metadata.get('source', '')}_{doc.metadata.get('page', '')}"

                if source_key not in seen_sources:
                    seen_sources.add(source_key)
                    sources.append({
                        'document': doc.metadata.get('source', 'Desconocido'),
                        'page': doc.metadata.get('page', 'N/A'),
                        'text': doc.page_content[:200]
                    })

            # Calcular confianza aproximada
            confidence = self._calculate_confidence(answer, source_docs)

            # Para opción múltiple, generar opciones
            options = []
            if question_type == 'multiple_choice':
                options = self._generate_options(answer, source_docs)

            return {
                'answer': answer,
                'sources': sources,
                'confidence': confidence,
                'options': options,
                'num_sources': len(sources)
            }

        except Exception as e:
            return {
                'answer': f"Error generando respuesta: {str(e)}",
                'sources': [],
                'confidence': 0.0,
                'options': [],
                'num_sources': 0
            }

    def _calculate_confidence(self, answer: str, source_docs: list) -> float:
        """Calcula un nivel de confianza aproximado."""
        if not source_docs:
            return 0.0

        # Factores de confianza
        has_sources = len(source_docs) > 0
        answer_length = min(len(answer) / 200, 1.0)
        source_count = min(len(source_docs) / self.top_k, 1.0)

        confidence = (
            0.4 * float(has_sources) +
            0.3 * answer_length +
            0.3 * source_count
        )

        return min(confidence, 0.95)

    def _generate_options(self, answer: str, source_docs: list) -> list:
        """Genera opciones para preguntas de opción múltiple."""
        import random

        # La primera opción es la respuesta correcta (resumida)
        correct_answer = answer[:100].split('.')[0] if answer else "No disponible"

        # Generar distractores del contexto
        distractors = []
        for doc in source_docs[1:4]:
            text = doc.page_content[:100].split('.')[0]
            if text and text != correct_answer:
                distractors.append(text)

        # Completar con opciones genéricas si es necesario
        generic_options = [
            "Información no especificada en el documento",
            "Dato no disponible en el contexto",
            "No se menciona explícitamente"
        ]

        while len(distractors) < 3:
            distractors.append(generic_options[len(distractors)])

        # Crear lista de opciones y mezclar
        all_options = [correct_answer] + distractors[:3]
        random.shuffle(all_options)

        return all_options
