"""
Motor de búsqueda avanzada para documentos PDF.
"""

import re
from typing import Dict, List, Any, Optional
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.metrics.pairwise import cosine_similarity
import numpy as np


class SearchEngine:
    """
    Motor de búsqueda que soporta búsqueda semántica,
    exacta y fuzzy en los documentos cargados.
    """

    def __init__(self):
        self.documents = {}
        self.indexed_chunks = []
        self.tfidf_vectorizer = None
        self.tfidf_matrix = None
        self.is_indexed = False

    def index_documents(self, documents: Dict[str, Any]):
        """
        Indexa los documentos para búsqueda eficiente.

        Args:
            documents: Diccionario de documentos procesados
        """
        self.documents = documents
        self.indexed_chunks = []

        for filename, doc_data in documents.items():
            pages = doc_data.get('pages', [])

            for page_num, page_text in enumerate(pages):
                # Dividir página en chunks de búsqueda
                chunks = self._create_search_chunks(page_text, filename, page_num + 1)
                self.indexed_chunks.extend(chunks)

        if self.indexed_chunks:
            # Crear índice TF-IDF
            texts = [chunk['text'] for chunk in self.indexed_chunks]

            self.tfidf_vectorizer = TfidfVectorizer(
                max_features=10000,
                ngram_range=(1, 2),
                min_df=1,
                max_df=0.95
            )

            self.tfidf_matrix = self.tfidf_vectorizer.fit_transform(texts)
            self.is_indexed = True

    def _create_search_chunks(self, text: str, filename: str, 
                               page_num: int) -> List[Dict]:
        """Crea chunks de texto para indexar."""
        chunks = []

        # Dividir por párrafos
        paragraphs = [p.strip() for p in text.split('\n\n') if p.strip()]

        for para_idx, paragraph in enumerate(paragraphs):
            if len(paragraph) > 50:  # Solo párrafos sustanciales
                chunks.append({
                    'text': paragraph,
                    'document': filename,
                    'page': page_num,
                    'paragraph': para_idx + 1,
                    'char_start': sum(len(p) for p in paragraphs[:para_idx]),
                    'char_end': sum(len(p) for p in paragraphs[:para_idx + 1])
                })

        return chunks

    def search(self, query: str, search_type: str = "Semántica",
               filter_docs: Optional[List[str]] = None,
               max_results: int = 10) -> List[Dict[str, Any]]:
        """
        Realiza una búsqueda en los documentos indexados.

        Args:
            query: Término o frase de búsqueda
            search_type: Tipo de búsqueda (Semántica, Exacta, Fuzzy)
            filter_docs: Lista de documentos a incluir
            max_results: Número máximo de resultados

        Returns:
            Lista de resultados ordenados por relevancia
        """
        if not self.is_indexed:
            return []

        # Filtrar chunks por documentos seleccionados
        chunks_to_search = self.indexed_chunks
        if filter_docs:
            chunks_to_search = [
                c for c in self.indexed_chunks 
                if c['document'] in filter_docs
            ]

        if not chunks_to_search:
            return []

        # Ejecutar búsqueda según tipo
        if search_type == "Exacta":
            results = self._exact_search(query, chunks_to_search)
        elif search_type == "Fuzzy":
            results = self._fuzzy_search(query, chunks_to_search)
        else:  # Semántica (por defecto)
            results = self._semantic_search(query, chunks_to_search)

        # Ordenar por relevancia y limitar resultados
        results.sort(key=lambda x: x.get('score', 0), reverse=True)
        return results[:max_results]

    def _semantic_search(self, query: str, 
                         chunks: List[Dict]) -> List[Dict[str, Any]]:
        """Búsqueda semántica usando TF-IDF."""
        try:
            # Filtrar índice a los chunks seleccionados
            chunk_indices = [
                idx for idx, chunk in enumerate(self.indexed_chunks)
                if chunk in chunks
            ]

            if not chunk_indices:
                return []

            # Vectorizar query
            query_vector = self.tfidf_vectorizer.transform([query])

            # Calcular similitud solo con chunks filtrados
            filtered_matrix = self.tfidf_matrix[chunk_indices]
            scores = cosine_similarity(query_vector, filtered_matrix)[0]

            # Crear resultados
            results = []
            for idx, score in enumerate(scores):
                if score > 0:
                    chunk = chunks[idx]
                    result = chunk.copy()
                    result['score'] = float(score)
                    result['search_type'] = 'semantic'
                    results.append(result)

            return results

        except Exception as e:
            return self._exact_search(query, chunks)

    def _exact_search(self, query: str, 
                      chunks: List[Dict]) -> List[Dict[str, Any]]:
        """Búsqueda exacta de texto."""
        results = []
        query_lower = query.lower()

        for chunk in chunks:
            text_lower = chunk['text'].lower()

            if query_lower in text_lower:
                # Contar ocurrencias
                count = text_lower.count(query_lower)
                score = min(count / 10, 1.0)  # Normalizar score

                result = chunk.copy()
                result['score'] = score
                result['occurrences'] = count
                result['search_type'] = 'exact'
                results.append(result)

        return results

    def _fuzzy_search(self, query: str, 
                      chunks: List[Dict]) -> List[Dict[str, Any]]:
        """Búsqueda fuzzy con tolerancia a errores."""
        try:
            from difflib import SequenceMatcher

            results = []
            query_lower = query.lower()
            query_words = query_lower.split()

            for chunk in chunks:
                text_lower = chunk['text'].lower()
                text_words = text_lower.split()

                # Calcular similitud fuzzy
                word_scores = []
                for q_word in query_words:
                    best_score = 0
                    for t_word in text_words:
                        ratio = SequenceMatcher(
                            None, q_word, t_word
                        ).ratio()
                        best_score = max(best_score, ratio)
                    word_scores.append(best_score)

                if word_scores:
                    avg_score = sum(word_scores) / len(word_scores)

                    if avg_score > 0.6:
                        result = chunk.copy()
                        result['score'] = avg_score
                        result['search_type'] = 'fuzzy'
                        results.append(result)

            return results

        except Exception:
            return self._exact_search(query, chunks)
