"""
Módulo de visualizaciones para el análisis de documentos PDF.
"""

import plotly.express as px
import plotly.graph_objects as go
from plotly.subplots import make_subplots
import pandas as pd
from typing import Dict, List, Any
from collections import Counter
import re


class Visualizer:
    """Clase para crear visualizaciones interactivas de los datos de PDFs."""

    # Paleta de colores consistente
    COLORS = px.colors.qualitative.Set3
    PRIMARY_COLOR = '#667eea'
    SECONDARY_COLOR = '#764ba2'

    def create_pages_chart(self, documents: Dict[str, Any]) -> go.Figure:
        """
        Crea un gráfico de distribución de páginas por documento.

        Args:
            documents: Diccionario de documentos procesados

        Returns:
            Figura de Plotly
        """
        data = [
            {'Documento': name, 'Páginas': doc.get('num_pages', 0)}
            for name, doc in documents.items()
        ]

        df = pd.DataFrame(data)

        fig = px.bar(
            df,
            x='Documento',
            y='Páginas',
            title='📑 Páginas por Documento',
            color='Páginas',
            color_continuous_scale='Viridis',
            text='Páginas'
        )

        fig.update_traces(textposition='outside')
        fig.update_layout(
            showlegend=False,
            plot_bgcolor='rgba(0,0,0,0)',
            paper_bgcolor='rgba(0,0,0,0)',
            font=dict(family="Arial, sans-serif"),
            title_font_size=16,
            xaxis=dict(tickangle=-45)
        )

        return fig

    def create_words_chart(self, documents: Dict[str, Any]) -> go.Figure:
        """
        Crea un gráfico de distribución de palabras.

        Args:
            documents: Diccionario de documentos procesados

        Returns:
            Figura de Plotly (pie chart)
        """
        labels = list(documents.keys())
        values = [doc.get('word_count', 0) for doc in documents.values()]

        fig = go.Figure(data=[go.Pie(
            labels=labels,
            values=values,
            hole=0.4,
            textinfo='label+percent',
            hovertemplate='<b>%{label}</b><br>Palabras: %{value:,}<extra></extra>'
        )])

        fig.update_layout(
            title='📝 Distribución de Palabras',
            title_font_size=16,
            paper_bgcolor='rgba(0,0,0,0)',
            showlegend=True,
            legend=dict(orientation="h", yanchor="bottom", y=-0.2)
        )

        return fig

    def create_word_frequency_chart(self, doc_data: Dict[str, Any]) -> go.Figure:
        """
        Crea un gráfico de frecuencia de palabras.

        Args:
            doc_data: Datos de un documento específico

        Returns:
            Figura de Plotly (bar chart horizontal)
        """
        text = doc_data.get('text', '').lower()

        # Extraer palabras (excluyendo muy cortas y comunes)
        words = re.findall(r'\b[a-záéíóúñ]{4,}\b', text)

        stop_words = {
            'para', 'como', 'pero', 'más', 'este', 'esta', 'estos', 'estas',
            'que', 'del', 'los', 'las', 'por', 'con', 'una', 'uno', 'también',
            'very', 'been', 'have', 'from', 'they', 'will', 'would', 'could',
            'sobre', 'entre', 'cuando', 'donde', 'desde', 'hasta', 'cada',
            'puede', 'debe', 'tiene', 'hacer', 'sido', 'estar', 'tiene'
        }

        filtered_words = [w for w in words if w not in stop_words]
        word_freq = Counter(filtered_words).most_common(15)

        if not word_freq:
            # Figura vacía con mensaje
            fig = go.Figure()
            fig.add_annotation(
                text="No hay suficiente texto para analizar",
                xref="paper", yref="paper",
                x=0.5, y=0.5, showarrow=False
            )
            return fig

        words_list, counts = zip(*word_freq)

        fig = go.Figure(go.Bar(
            x=list(counts),
            y=list(words_list),
            orientation='h',
            marker=dict(
                color=list(counts),
                colorscale='Viridis',
                showscale=True
            ),
            text=list(counts),
            textposition='outside'
        ))

        fig.update_layout(
            title='🔤 Palabras Más Frecuentes',
            title_font_size=16,
            xaxis_title='Frecuencia',
            yaxis_title='Palabra',
            paper_bgcolor='rgba(0,0,0,0)',
            plot_bgcolor='rgba(0,0,0,0)',
            height=500
        )

        return fig

    def create_qa_activity_chart(self, chat_history: List[Dict]) -> go.Figure:
        """
        Crea un gráfico de actividad de Q&A.

        Args:
            chat_history: Historial de conversación

        Returns:
            Figura de Plotly
        """
        if not chat_history:
            fig = go.Figure()
            fig.add_annotation(
                text="Sin datos de actividad aún",
                xref="paper", yref="paper",
                x=0.5, y=0.5, showarrow=False
            )
            return fig

        # Preparar datos
        timestamps = [entry.get('timestamp', str(i)) 
                     for i, entry in enumerate(chat_history)]
        response_times = [entry.get('response_time', 0) 
                         for entry in chat_history]
        question_types = [entry.get('question_type', 'open') 
                         for entry in chat_history]
        confidences = [entry.get('confidence', 0) 
                      for entry in chat_history]

        # Crear subplots
        fig = make_subplots(
            rows=2, cols=1,
            subplot_titles=(
                '⏱️ Tiempo de Respuesta por Pregunta',
                '📊 Confianza por Pregunta'
            ),
            vertical_spacing=0.15
        )

        # Gráfico de tiempos
        fig.add_trace(
            go.Scatter(
                x=list(range(1, len(response_times) + 1)),
                y=response_times,
                mode='lines+markers',
                name='Tiempo (s)',
                line=dict(color=self.PRIMARY_COLOR, width=2),
                marker=dict(size=8)
            ),
            row=1, col=1
        )

        # Gráfico de confianza
        fig.add_trace(
            go.Bar(
                x=list(range(1, len(confidences) + 1)),
                y=confidences,
                name='Confianza',
                marker_color=self.SECONDARY_COLOR,
                text=[f"{c:.0%}" for c in confidences],
                textposition='outside'
            ),
            row=2, col=1
        )

        fig.update_layout(
            title='📈 Actividad de Q&A',
            title_font_size=16,
            paper_bgcolor='rgba(0,0,0,0)',
            plot_bgcolor='rgba(0,0,0,0)',
            showlegend=True,
            height=500
        )

        return fig

    def create_document_comparison_chart(self, 
                                          documents: Dict[str, Any]) -> go.Figure:
        """
        Crea un gráfico de radar para comparar documentos.

        Args:
            documents: Diccionario de documentos

        Returns:
            Figura de Plotly (radar chart)
        """
        if len(documents) < 2:
            fig = go.Figure()
            fig.add_annotation(
                text="Se necesitan al menos 2 documentos para comparar",
                xref="paper", yref="paper",
                x=0.5, y=0.5, showarrow=False
            )
            return fig

        categories = ['Páginas', 'Palabras', 'Caracteres', 'Densidad Léxica']

        # Normalizar valores
        max_pages = max(d.get('num_pages', 1) for d in documents.values())
        max_words = max(d.get('word_count', 1) for d in documents.values())
        max_chars = max(d.get('char_count', 1) for d in documents.values())

        fig = go.Figure()

        for doc_name, doc_data in documents.items():
            # Calcular densidad léxica (palabras únicas / total)
            text = doc_data.get('text', '')
            words = text.lower().split()
            lexical_density = (
                len(set(words)) / len(words) if words else 0
            )

            values = [
                (doc_data.get('num_pages', 0) / max_pages) * 100,
                (doc_data.get('word_count', 0) / max_words) * 100,
                (doc_data.get('char_count', 0) / max_chars) * 100,
                lexical_density * 100
            ]

            fig.add_trace(go.Scatterpolar(
                r=values + [values[0]],  # Cerrar el polígono
                theta=categories + [categories[0]],
                fill='toself',
                name=doc_name[:30],
                opacity=0.6
            ))

        fig.update_layout(
            polar=dict(
                radialaxis=dict(
                    visible=True,
                    range=[0, 100]
                )
            ),
            title='🔍 Comparación de Documentos',
            title_font_size=16,
            showlegend=True,
            paper_bgcolor='rgba(0,0,0,0)'
        )

        return fig
